def cache_sim(capacity, ttl, ops):
    cache = {}  # key -> (value, write_time)
    lru_order = []  # list of keys in order of recency
    results = []

    for op in ops:
        op_type = op[0]
        t = op[1]
        key = op[2]

        # Remove expired entries
        expired_keys = []
        for k in cache:
            value, write_time = cache[k]
            if write_time + ttl <= t:
                expired_keys.append(k)

        for k in expired_keys:
            del cache[k]
            if k in lru_order:
                lru_order.remove(k)

        if op_type == 'put':
            value = op[3]

            # If key already exists, remove it from lru_order
            if key in cache:
                lru_order.remove(key)
            else:
                # If cache is full, evict LRU entry
                if len(cache) >= capacity:
                    lru_key = lru_order.pop(0)
                    del cache[lru_key]

            # Add the new entry
            cache[key] = (value, t)
            lru_order.append(key)

        elif op_type == 'get':
            if key in cache:
                value, write_time = cache[key]
                # Move to end (most recently used)
                lru_order.remove(key)
                lru_order.append(key)
                results.append(value)
            else:
                results.append(-1)

    return results

